// Fixture approvals use complete generated build identities and exact JSON
// wire values without relaxing historical plan or runtime validation.
package main

import (
	"bytes"
	"encoding/json"
	"maps"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"

	"github.com/ethereum/go-ethereum/crypto"
)

// The real generated bytecode, not stale public fixture pins, determines the
// in-memory test approval. The public release file remains unchanged.
func TestValidatorEvidenceFixtureReleaseLockMatchesGeneratedBodies(t *testing.T) {
	path := filepath.Join("..", "deploy", "testnet", "release.lock.yml")
	before, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	lock := testReleaseLockFixture(t)
	if err := verifyFinalReleaseLockRuntimeBuild(lock); err != nil {
		t.Fatalf("fixture lock does not authenticate generated runtimes: %v", err)
	}
	artifact, err := currentValidatorEvidenceArtifact()
	if err != nil {
		t.Fatal(err)
	}
	for key, expected := range map[string]string{
		"validator_evidence_artifact_hash":       artifact.FoundryArtifactHash,
		"validator_evidence_runtime_hash":        crypto.Keccak256Hash(hexBytes(artifact.RuntimeBytecode)).Hex(),
		"validator_evidence_storage_layout_hash": artifact.StorageLayoutHash,
	} {
		actual, err := lockString(lock.EVMBuild, key)
		if err != nil || actual != expected {
			t.Fatalf("fixture %s is not the generated identity: got=%s want=%s error=%v", key, actual, expected, err)
		}
		missing := *lock
		missing.EVMBuild = maps.Clone(lock.EVMBuild)
		delete(missing.EVMBuild, key)
		if err := validateReleaseLockStatic(&missing); err == nil || !strings.Contains(err.Error(), key) {
			t.Fatalf("missing %s fixture authority was accepted: %v", key, err)
		}
	}
	if lock.EVMBuild["abi_hash"] != generatedABIHash() {
		t.Fatal("fixture ABI identity differs from the generated contract census")
	}
	for _, spec := range finalReleaseRuntimeRootSpecs {
		changed := *lock
		changed.EVMBuild = maps.Clone(lock.EVMBuild)
		changed.EVMBuild[spec.releaseLockKey] = finalTestHex(0x81)
		if err := validateReleaseLockStatic(&changed); err != nil {
			t.Fatalf("%s mutation is not a well-shaped prerequisite: %v", spec.releaseLockKey, err)
		}
		if err := verifyFinalReleaseLockRuntimeBuild(&changed); err == nil || !strings.Contains(err.Error(), spec.releaseLockKey) {
			t.Fatalf("%s substituted runtime was accepted: %v", spec.releaseLockKey, err)
		}
	}
	after, err := os.ReadFile(path)
	if err != nil || !bytes.Equal(before, after) {
		t.Fatalf("fixture generation rewrote public release approval: %v", err)
	}
}

// Exercise the actual lightweight anchor constructor before the expensive
// release-scale graph so incomplete fixture inputs have a direct regression.
func TestValidatorEvidenceFixtureDeploymentAnchorsBindCompleteSource(t *testing.T) {
	cfg, _, payloads := validatorEvidenceInstallTest(t)
	// This case starts from an explicitly stale, owned dependency approval;
	// the current lock is already complete and rebinding it is idempotent.
	staleLock := *cfg.Release
	staleLock.Dependencies = maps.Clone(cfg.Release.Dependencies)
	staleImage := "synthetic-redis.example/fixture@sha256:" + strings.Repeat("81", 32)
	if staleLock.Dependencies["redis"] == staleImage {
		t.Fatal("stale approval fixture unexpectedly equals the current lock")
	}
	staleLock.Dependencies["redis"] = staleImage
	if err := validateReleaseLockStatic(&staleLock); err != nil {
		t.Fatalf("stale private approval is not well-shaped: %v", err)
	}
	cfg.Release = &staleLock
	roles, err := derivePublicRoles(cfg)
	if err != nil {
		t.Fatal(err)
	}
	facts := *testSetupFacts()
	facts.DeployerNonce = payloads.Manifest.InitialNonce
	plan, err := buildPlan(cfg, &facts, roles, time.Unix(1, 0))
	if err != nil {
		t.Fatal(err)
	}
	if plan.ValidatorEvidenceSource.ReleaseLock.Dependencies["redis"] != staleImage {
		t.Fatal("original plan did not bind the explicit stale private approval")
	}
	beforeHash := plan.PlanHash
	var source FinalSemanticEvidence
	artifacts := map[string][]byte{}
	configureFinalSemanticFixtureDeploymentAnchors(t, cfg, &source, artifacts, plan)
	if plan.PlanHash == beforeHash {
		t.Fatal("complete lock fixture failed to establish a distinct approval")
	}
	if !finalJSONEqual(plan.ValidatorEvidenceSource.ReleaseLock, cfg.Release) {
		t.Fatal("fixture lock was not rebound into the original source archive")
	}
	raw, err := json.Marshal(plan)
	if err != nil {
		t.Fatal(err)
	}
	reopened, err := decodePersistedPlanBytesForHistory(raw, true)
	if err != nil || reopened == nil || reopened.PlanHash != plan.PlanHash {
		t.Fatalf("complete fixture historical source was refused: %v", err)
	}
	locator := source.ReleaseLockArtifact
	lockRaw := artifacts[locator.URI]
	if locator.Kind != "release-lock" || locator.ContentHash != bytesSHA256(lockRaw) || locator.SizeBytes != uint64(len(lockRaw)) {
		t.Fatal("fixture lock artifact differs from its exact content locator")
	}
	decoded, err := decodeReleaseLockBytes(lockRaw)
	if err != nil || !finalJSONEqual(decoded, cfg.Release) {
		t.Fatalf("fixture lock wire differs from its approved authority: %v", err)
	}
	if err := verifyFinalReleaseLockRuntimeBuild(decoded); err != nil {
		t.Fatalf("fixture lock does not authenticate generated runtimes: %v", err)
	}
	expected, err := finalReleaseRuntimeRootsForPlan(reopened, decoded)
	if err != nil || len(expected) != len(finalReleaseRuntimeRootSpecs) || !finalJSONEqual(expected, source.Deployment.RuntimeRoots) {
		t.Fatalf("fixture runtime census lost exact approved roots: %v", err)
	}
	for _, key := range []string{"validator_evidence_artifact_hash", "validator_evidence_runtime_hash", "validator_evidence_storage_layout_hash"} {
		var changed SetupPlan
		if err := json.Unmarshal(raw, &changed); err != nil {
			t.Fatal(err)
		}
		value, err := lockString(changed.ValidatorEvidenceSource.ReleaseLock.EVMBuild, key)
		if err != nil || len(value) == 0 {
			t.Fatalf("%s source identity prerequisite: %v", key, err)
		}
		replacement := byte('0')
		if value[len(value)-1] == replacement {
			replacement = '1'
		}
		changed.ValidatorEvidenceSource.ReleaseLock.EVMBuild[key] = value[:len(value)-1] + string(replacement)
		if err := validateValidatorEvidenceSource(&changed, true); err == nil {
			t.Fatalf("%s archive substitution was accepted", key)
		}
	}
}

// Rebinding a current approval is byte-idempotent, while each source archive,
// input lock and emitted lock artifact retains its independent ownership.
func TestValidatorEvidenceFixtureDeploymentAnchorsKeepCurrentApprovalAndOwnSources(t *testing.T) {
	path := filepath.Join("..", "deploy", "testnet", "release.lock.yml")
	publicBefore, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	cfg, _, payloads := validatorEvidenceInstallTest(t)
	originalLock := cfg.Release
	roles, err := derivePublicRoles(cfg)
	if err != nil {
		t.Fatal(err)
	}
	facts := *testSetupFacts()
	facts.DeployerNonce = payloads.Manifest.InitialNonce
	plan, err := buildPlan(cfg, &facts, roles, time.Unix(1, 0))
	if err != nil {
		t.Fatal(err)
	}
	originalSource := plan.ValidatorEvidenceSource
	before, err := json.Marshal(plan)
	if err != nil {
		t.Fatal(err)
	}
	beforeHash := plan.PlanHash
	var source FinalSemanticEvidence
	artifacts := map[string][]byte{}
	configureFinalSemanticFixtureDeploymentAnchors(t, cfg, &source, artifacts, plan)
	after, err := json.Marshal(plan)
	if err != nil || plan.PlanHash != beforeHash || !bytes.Equal(before, after) {
		t.Fatalf("current approval rebind changed the original plan: %v", err)
	}
	if cfg.Release == originalLock || plan.ValidatorEvidenceSource == originalSource || plan.ValidatorEvidenceSource.ReleaseLock == cfg.Release {
		t.Fatal("anchor constructor borrowed mutable lock or source ownership")
	}
	lockLocator := source.ReleaseLockArtifact
	lockRaw := append([]byte(nil), artifacts[lockLocator.URI]...)
	if len(lockRaw) == 0 || lockLocator.ContentHash != bytesSHA256(lockRaw) || lockLocator.SizeBytes != uint64(len(lockRaw)) {
		t.Fatal("current anchor did not emit the exact lock artifact")
	}
	originalLock.Dependencies["redis"] = "changed original owned lock"
	originalSource.ReleaseLock.Dependencies["redis"] = "changed original owned source"
	currentRaw, err := canonicalReleaseLockBytes(cfg.Release)
	if err != nil || !bytes.Equal(currentRaw, lockRaw) {
		t.Fatalf("former owners changed the rebound approval: %v", err)
	}
	cfg.Release.Dependencies["redis"] = "changed rebound input lock"
	detached, err := json.Marshal(plan)
	if err != nil || !bytes.Equal(detached, before) || !bytes.Equal(artifacts[lockLocator.URI], lockRaw) {
		t.Fatalf("input lock mutation changed the archived plan or emitted bytes: %v", err)
	}
	configureFinalSemanticFixtureDeploymentAnchors(t, cfg, &source, artifacts, plan)
	repeated, err := json.Marshal(plan)
	if err != nil || plan.PlanHash != beforeHash || !bytes.Equal(repeated, before) || source.ReleaseLockArtifact != lockLocator || !bytes.Equal(artifacts[lockLocator.URI], lockRaw) {
		t.Fatalf("fresh current approval inherited prior private mutations: %v", err)
	}
	publicAfter, err := os.ReadFile(path)
	if err != nil || !bytes.Equal(publicBefore, publicAfter) {
		t.Fatalf("anchor fixture rewrote the public release lock: %v", err)
	}
}

// The original source's UseNumber and native action's DecimalUint zero both
// preserve full canonical JSON identity across genuine plan archival.
func TestValidatorEvidenceFixtureCanonicalWireIdentityRefusesDrift(t *testing.T) {
	cfg, _, payloads := validatorEvidenceInstallTest(t)
	cfg.Release = testReleaseLockFixture(t)
	roles, err := derivePublicRoles(cfg)
	if err != nil {
		t.Fatal(err)
	}
	facts := *testSetupFacts()
	facts.DeployerNonce = payloads.Manifest.InitialNonce
	plan, err := buildPlan(cfg, &facts, roles, time.Unix(1, 0))
	if err != nil {
		t.Fatal(err)
	}
	raw, err := json.Marshal(plan)
	if err != nil {
		t.Fatal(err)
	}
	reopened, err := decodePersistedPlanBytesForHistory(raw, true)
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := plan.ValidatorEvidenceSource.ReleaseLock.EVMBuild["optimizer_runs"].(json.Number); !ok {
		t.Fatal("original archive did not retain the actual UseNumber representation")
	}
	if _, ok := reopened.ValidatorEvidenceSource.ReleaseLock.EVMBuild["optimizer_runs"].(float64); !ok {
		t.Fatal("reopened archive did not exercise JSON interface number decoding")
	}
	if reflect.DeepEqual(plan.ValidatorEvidenceSource, reopened.ValidatorEvidenceSource) || !finalJSONEqual(plan.ValidatorEvidenceSource, reopened.ValidatorEvidenceSource) {
		t.Fatal("archive representation changed the exact source wire identity")
	}
	for _, id := range []string{"fleet.commitment.1", "fleet.refresh.commitment.1"} {
		before := actionByID(t, plan, id)
		after := actionByID(t, reopened, id)
		if before.Spend.EVMGasWei != "" || after.Spend.EVMGasWei != "0" || reflect.DeepEqual(before, after) || !finalJSONEqual(before, after) {
			t.Fatalf("%s did not preserve the genuine native zero-gas wire transition", id)
		}
		for _, fault := range []string{"target", "intent", "gas", "parameters", "dependencies"} {
			var changed Action
			encoded, err := json.Marshal(after)
			if err != nil {
				t.Fatal(err)
			}
			if err := json.Unmarshal(encoded, &changed); err != nil {
				t.Fatal(err)
			}
			switch fault {
			case "target":
				changed.Target += "-foreign"
			case "intent":
				changed.IntentHash = finalTestHex(0x83)
			case "gas":
				changed.Spend.EVMGasWei = "1"
			case "parameters":
				changed.Parameters["fixture_unapproved"] = "true"
			case "dependencies":
				changed.DependsOn = append(changed.DependsOn, "fixture.unapproved")
			}
			if finalJSONEqual(before, changed) {
				t.Fatalf("%s %s drift disappeared from full action wire comparison", id, fault)
			}
		}
	}
	for _, fault := range []string{"number", "image", "artifact"} {
		var changed ValidatorEvidenceSource
		encoded, err := json.Marshal(reopened.ValidatorEvidenceSource)
		if err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(encoded, &changed); err != nil {
			t.Fatal(err)
		}
		switch fault {
		case "number":
			changed.ReleaseLock.EVMBuild["optimizer_runs"] = json.Number("201")
		case "image":
			changed.ReleaseLock.Runtime.Image += "-foreign"
		case "artifact":
			changed.Artifact.RuntimeBytecodeHash = finalTestHex(0x84)
		}
		if finalJSONEqual(plan.ValidatorEvidenceSource, &changed) {
			t.Fatalf("%s drift disappeared from full source wire comparison", fault)
		}
	}
}
